// test_display.mjs - the display ROM decode against known patterns.
//
// js/display.js's digitSegments must read roms/output-display.hex
// exactly the way the output module's hardware does (U37/U38/U44/U45;
// the encoding is docs/hardware.md, "The display", generated by
// tools/genroms.py). These checks mirror genroms.py's SEG_DIGITS /
// SEG_HEX tables and the leading-zero blanking.
//
//   node web/test/test_display.mjs

import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { parseImage } from "../js/hex.js";
import { digitSegments } from "../js/display.js";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const rom = parseImage(
  readFileSync(join(ROOT, "roms", "output-display.hex")), 2048);

const SEG = [0x7e, 0x30, 0x6d, 0x79, 0x33, 0x5b, 0x5f, 0x70, 0x7f, 0x7b];
const SEG_HEX = SEG.concat([0x77, 0x1f, 0x4e, 0x3d, 0x4f, 0x47]);
const BLANK = 0x00;

const checks = [
  // decimal (A10 = 1): ones/tens/hundreds, leading zeros blanked
  ["dec 0", () => [
    digitSegments(rom, 0, 0, true) === SEG[0],
    digitSegments(rom, 0, 1, true) === BLANK,
    digitSegments(rom, 0, 2, true) === BLANK,
    digitSegments(rom, 0, 3, true) === BLANK,
  ]],
  ["dec 255", () => [
    digitSegments(rom, 255, 0, true) === SEG[5],
    digitSegments(rom, 255, 1, true) === SEG[5],
    digitSegments(rom, 255, 2, true) === SEG[2],
  ]],
  ["dec 100", () => [
    digitSegments(rom, 100, 0, true) === SEG[0],
    digitSegments(rom, 100, 1, true) === SEG[0],
    digitSegments(rom, 100, 2, true) === SEG[1],
  ]],
  // hexadecimal (A10 = 0): two nibbles, high blanked under 0x10
  ["hex 0xaf", () => [
    digitSegments(rom, 0xaf, 0, false) === SEG_HEX[15],
    digitSegments(rom, 0xaf, 1, false) === SEG_HEX[10],
  ]],
  ["hex 5", () => [
    digitSegments(rom, 5, 0, false) === SEG_HEX[5],
    digitSegments(rom, 5, 1, false) === BLANK,
  ]],
];

let failures = 0;
for (const [name, run] of checks) {
  const results = run();
  const ok = results.every(Boolean);
  console.log("  " + name.padEnd(10) + (ok ? "PASS" : "FAIL"));
  if (!ok) failures++;
}
if (failures) {
  console.error("test_display: " + failures + " FAILURES");
  process.exit(1);
}
console.log("test_display: the display decode matches the ROM");
